const takeMediaOrphans = `-- name: TakeMediaOrphans :many
SELECT id, storage_key
FROM media_object
WHERE deleted_at IS NOT NULL AND deleted_at <= $1
ORDER BY deleted_at
LIMIT $2
`

type TakeMediaOrphansParams struct {
	MarkedBefore pgtype.Timestamptz
	Batch        int32
}

type TakeMediaOrphansRow struct {
	ID         pgtype.UUID
	StorageKey string
}

// The third pass: marked rows past their grace, handed to the purge job. The keys travel in the
// job's payload, so the byte deletion needs no transaction of its own to find them.
func (q *Queries) TakeMediaOrphans(ctx context.Context, arg TakeMediaOrphansParams) ([]TakeMediaOrphansRow, error) {
	rows, err := q.db.Query(ctx, takeMediaOrphans, arg.MarkedBefore, arg.Batch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TakeMediaOrphansRow{}
	for rows.Next() {
		var i TakeMediaOrphansRow
		if err := rows.Scan(&i.ID, &i.StorageKey); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

